package com.rdzim.memorycheck;
import android.content.Context;
import android.content.SharedPreferences;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.text.TextUtils;
import android.view.Gravity;
import android.view.View;
import android.widget.*;
public final class FloatingMenu extends LinearLayout {
    public interface Actions {void collapse(boolean value);void close();}
    private final SharedPreferences prefs;private final LinearLayout panel;private final ImageView bubble;private final TextView handle,fovLabel,size,espStatus,aimStatus;private final SeekBar fov;private final CheckBox aim,esp,crosshair;private final LinearLayout sizeChoices;
    private final Button[] targets=new Button[3];private final CheckBox showFov;
    private final CheckBox[] visuals=new CheckBox[6];private final String[] keys={"esp_line","esp_box","esp_skeleton","esp_name","esp_health","esp_distance"};private final Button[] shapeButtons=new Button[2];private final EspColorSlider colorSlider;private final TextView colorLabel;private boolean refreshing;
    private int dp(int n){return MenuLook.dp(getContext(),n);}private TextView label(String v,int sp,int color){return MenuLook.text(getContext(),v,sp,color);}private Button button(String v){return MenuLook.button(getContext(),v);}
    private LinearLayout column(){LinearLayout l=new LinearLayout(getContext());l.setOrientation(VERTICAL);return l;}
    private void title(LinearLayout page,String text){TextView t=label(text,10,MenuLook.MUTED);t.setLetterSpacing(.12f);t.setPadding(0,dp(8),0,dp(6));page.addView(t);}
    @SuppressWarnings("deprecation") private CheckBox option(LinearLayout page,String name,String key,boolean initial){CheckBox s=new CheckBox(getContext());s.setText(name);s.setTextSize(13);s.setTextColor(MenuLook.INK);s.setPadding(dp(2),0,dp(2),0);s.setButtonTintList(MenuLook.thumb());s.setChecked(prefs.getBoolean(key,initial));page.addView(s,new LayoutParams(-1,dp(36)));s.setOnCheckedChangeListener((b,on)->{if(!refreshing)prefs.edit().putBoolean(key,on).apply();});return s;}
    public FloatingMenu(Context c,SharedPreferences preferences,Actions actions){
        super(c);prefs=preferences;setOrientation(VERTICAL);
        bubble=MenuLook.portrait(c,true);bubble.setElevation(dp(6));bubble.setContentDescription("Abrir Arroz Menu. Arraste para mover.");addView(bubble,new LayoutParams(dp(44),dp(44)));bubble.setOnClickListener(v->actions.collapse(false));
        panel=column();GradientDrawable back=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xff18213a,0xff0d1529});back.setCornerRadius(dp(24));back.setStroke(dp(1),0xff4b527e);panel.setBackground(back);panel.setClipToOutline(true);addView(panel,new LayoutParams(-1,-1));
        LinearLayout header=new LinearLayout(c);header.setGravity(Gravity.CENTER_VERTICAL);header.setBackground(MenuLook.gradient(c,0xff684ec7,0xff326d9e,0));header.setPadding(dp(10),dp(6),dp(8),dp(6));panel.addView(header,new LayoutParams(-1,dp(40)));header.addView(MenuLook.portrait(c,false),new LayoutParams(dp(24),dp(24)));
        handle=label("  ARROZ MENU",13,MenuLook.INK);handle.setTypeface(null,Typeface.BOLD);handle.setGravity(Gravity.CENTER_VERTICAL);handle.setContentDescription("Arraste para mover o painel");header.addView(handle,new LayoutParams(0,-1,1));Button minimize=button("−"),close=button("×");header.addView(minimize,new LayoutParams(dp(28),dp(28)));LayoutParams closeLp=new LayoutParams(dp(28),dp(28));closeLp.leftMargin=dp(4);header.addView(close,closeLp);minimize.setContentDescription("Recolher para a foto");close.setContentDescription("Encerrar painel");minimize.setOnClickListener(v->actions.collapse(true));close.setOnClickListener(v->actions.close());
        LinearLayout tabs=new LinearLayout(c);tabs.setPadding(dp(9),0,dp(9),dp(7));panel.addView(tabs,new LayoutParams(-1,dp(39)));String[] tabNames={"Mira","Visual","Painel"};Button[] tabButtons=new Button[3];
        ScrollView scroll=new ScrollView(c);scroll.setFillViewport(false);scroll.setVerticalScrollBarEnabled(false);panel.addView(scroll,new LayoutParams(-1,0,1));LinearLayout content=column();content.setPadding(dp(12),0,dp(12),dp(10));scroll.addView(content);LinearLayout[] pages={column(),column(),column()};for(int i=0;i<3;i++){final int selected=i;Button b=button(tabNames[i]);tabButtons[i]=b;LayoutParams lp=new LayoutParams(0,-1,1);if(i>0)lp.leftMargin=dp(4);tabs.addView(b,lp);content.addView(pages[i],new LayoutParams(-1,-2));pages[i].setVisibility(i==0?VISIBLE:GONE);MenuLook.select(b,i==0);b.setOnClickListener(v->{for(int k=0;k<3;k++){pages[k].setVisibility(k==selected?VISIBLE:GONE);MenuLook.select(tabButtons[k],k==selected);}scroll.scrollTo(0,0);});}
        LinearLayout a=pages[0];aim=option(a,"Ativar mira","aim_enabled",false);aimStatus=label("",10,MenuLook.MUTED);aimStatus.setMaxLines(2);aimStatus.setEllipsize(TextUtils.TruncateAt.END);a.addView(aimStatus);title(a,"ALVO");LinearLayout regions=new LinearLayout(c);a.addView(regions);String[] regionsText={"Cabeça","Peito","Quadril"};for(int i=0;i<3;i++){final int target=i;Button b=button(regionsText[i]);targets[i]=b;LayoutParams lp=new LayoutParams(0,dp(34),1);if(i>0)lp.leftMargin=dp(4);regions.addView(b,lp);b.setOnClickListener(view->prefs.edit().putInt("aim_target",target).apply());}showFov=option(a,"Mostrar FOV","aim_show_fov",true);title(a,"ÁREA DA MIRA");fovLabel=label("",12,MenuLook.ACCENT);a.addView(fovLabel);fov=new SeekBar(c);fov.setMax(360);fov.setProgressTintList(android.content.res.ColorStateList.valueOf(MenuLook.ACCENT));fov.setThumbTintList(android.content.res.ColorStateList.valueOf(MenuLook.ACCENT));a.addView(fov,new LayoutParams(-1,dp(38)));fov.setContentDescription("FOV zero a 360");fov.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int value,boolean user){fovLabel.setText("FOV  "+value);if(user)prefs.edit().putInt("aim_fov",value).apply();}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});
        crosshair=option(a,"Mira fixa","enabled",true);LinearLayout sizing=new LinearLayout(c);sizing.setGravity(Gravity.CENTER_VERTICAL);a.addView(sizing,new LayoutParams(-1,dp(32)));size=label("",11,MenuLook.MUTED);sizing.addView(size,new LayoutParams(0,-2,1));Button less=button("−"),more=button("+");sizing.addView(less,new LayoutParams(dp(32),dp(28)));LayoutParams moreLp=new LayoutParams(dp(32),dp(28));moreLp.leftMargin=dp(4);sizing.addView(more,moreLp);less.setOnClickListener(v->changeSize(-2));more.setOnClickListener(v->changeSize(2));
        LinearLayout v=pages[1];esp=option(v,"ESP","esp_enabled",false);espStatus=label("",10,MenuLook.MUTED);espStatus.setMaxLines(2);espStatus.setEllipsize(TextUtils.TruncateAt.END);v.addView(espStatus);String[] names={"ESP Linha","ESP Box","ESP Esqueleto","ESP Name","ESP Vida","ESP Distância"};boolean[] defaults={true,true,false,true,false,false};for(int i=0;i<visuals.length;i++)visuals[i]=option(v,names[i],keys[i],defaults[i]);title(v,"COR DA ESP");colorLabel=label("",12,MenuLook.INK);colorLabel.setTypeface(Typeface.MONOSPACE);v.addView(colorLabel);colorSlider=new EspColorSlider(c);v.addView(colorSlider,new LayoutParams(-1,dp(44)));colorSlider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar slider,int value,boolean user){if(user&&!refreshing){int color=EspPalette.color(value);colorSlider.setSelectionColor(color);colorLabel.setText(String.format(java.util.Locale.ROOT,"#%06X",color&0xffffff));colorLabel.setTextColor(color);prefs.edit().putInt("esp_color_position",value).putInt("esp_color",color).apply();}}public void onStartTrackingTouch(SeekBar slider){}public void onStopTrackingTouch(SeekBar slider){}});
        LinearLayout settings=pages[2];title(settings,"TAMANHO DO PAINEL");sizeChoices=MenuLook.sizes(c,prefs);settings.addView(sizeChoices);title(settings,"FORMATO DA MIRA");LinearLayout shapes=new LinearLayout(c);settings.addView(shapes);for(int i=0;i<2;i++){final boolean round=i==1;Button shape=button(round?"Círculo":"Cruz");shapeButtons[i]=shape;LayoutParams lp=new LayoutParams(0,dp(34),1);if(i>0)lp.leftMargin=dp(5);shapes.addView(shape,lp);shape.setOnClickListener(view->prefs.edit().putBoolean("circle",round).apply());}title(settings,"COR DA MIRA");LinearLayout fixedColors=new LinearLayout(c);settings.addView(fixedColors);for(int color:new int[]{0xff79f2bf,0xff58ddff,0xffbb8bff,Color.WHITE}){Button dot=button("●");dot.setTextColor(color);dot.setTextSize(21);fixedColors.addView(dot,new LayoutParams(0,dp(34),1));dot.setOnClickListener(view->prefs.edit().putInt("color",color).apply());}TextView version=label("ARROZ MENU  /  3.1.7",9,MenuLook.MUTED);version.setPadding(0,dp(12),0,0);settings.addView(version);
        setCollapsed(false);refresh();
    }
    private void changeSize(int delta){prefs.edit().putInt("size",Math.max(6,Math.min(28,prefs.getInt("size",14)+delta))).apply();}
    public void refresh(){refreshing=true;showFov.setChecked(prefs.getBoolean("aim_show_fov",true));int target=Math.max(0,Math.min(2,prefs.getInt("aim_target",0)));for(int i=0;i<3;i++)MenuLook.select(targets[i],i==target);aim.setChecked(prefs.getBoolean("aim_enabled",false));esp.setChecked(prefs.getBoolean("esp_enabled",false));crosshair.setChecked(prefs.getBoolean("enabled",true));int f=Math.max(0,Math.min(360,prefs.getInt("aim_fov",130)));fov.setProgress(f);fovLabel.setText("FOV  "+f);size.setText("Tamanho  "+prefs.getInt("size",14));boolean[] defaults={true,true,false,true,false,false};for(int i=0;i<visuals.length;i++)visuals[i].setChecked(prefs.getBoolean(keys[i],defaults[i]));refreshStatus();int color=prefs.getInt("esp_color",0xff79ffb7),position=prefs.getInt("esp_color_position",-1);if(position<0||position>EspPalette.MAX||EspPalette.color(position)!=color)position=EspPalette.position(color);colorSlider.setProgress(position);colorSlider.setSelectionColor(color);colorLabel.setText(String.format(java.util.Locale.ROOT,"#%06X",color&0xffffff));colorLabel.setTextColor(color);MenuLook.refreshSizes(sizeChoices,prefs);boolean round=prefs.getBoolean("circle",false);MenuLook.select(shapeButtons[0],!round);MenuLook.select(shapeButtons[1],round);refreshing=false;}
    public void refreshStatus(){aimStatus.setText(aim.isChecked()?prefs.getString("aim_status","Conectando…"):"Desligado");espStatus.setText(esp.isChecked()?prefs.getString("esp_status","Conectando…"):"Desligada");}
    public void setCollapsed(boolean value){panel.setVisibility(value?GONE:VISIBLE);bubble.setVisibility(value?VISIBLE:GONE);}public View dragHandle(){return handle;}public View bubbleHandle(){return bubble;}
}
